INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "刘承钧", "aliases": ["劉承鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "刘承训（契丹册命使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹骠骑大将军、知内侍省事。《通鉴》显德元年末记他奉契丹命册立刘承钧为北汉皇帝。与刘知远的同名儿子分开；生卒年未载，册命年另有史书异说。", "biography": null, "status": "draft", "id": "bee62914-20c0-5a1f-aba3-06499d958db4"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "苻彦通", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "溆州地方部族首领。马希萼攻破长沙时掠得府库财物，后来在溪洞地区称王。王虔朗劝说后，他去王号、献铜鼓，获王逵承制任为黔中节度使。生卒年未载，自称苻秦后裔不当已证族谱。", "biography": null, "status": "draft", "id": "45b2801a-dc2a-5038-810c-c838efafb895"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "王虔朗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "桂州人，王逵部将。《通鉴》954年末记其自请出使苻彦通，劝其去王号归附，获任都指挥使并参与府政。生卒年未载。", "biography": null, "status": "draft", "id": "855f1d3e-f8c6-5280-a16e-98e8f88a47bf"}, {"name": "刘瑫（楚蛮酋）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚地地方首领，任土团都指挥使。952年被任为西境镇遏使，防备苻彦通。原书未明具体族属，不与后周文官刘涛混同，生卒年未载。", "biography": null, "status": "draft", "id": "db1c2c95-b453-50d5-8ca1-a92fd75786e3"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

